"""Matter management for LexManage.

Written by the factory WRITER role (codewhale exec). Authored by the coding agent in the WRITER seat:
this module is the capability's real handler, not a contract template.

Domain: Centralized matter file: number, client, practice area, responsible attorney, stage, deadline and the matter brief.

Blocks (registry-verified, dispatched by keyword action):
  workflow         run              Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.
  database         insert           Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.
  document_engine  parse            Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.
  notification     send             Centralized tracking and management of legal matters, including case details, deadlines, and associated documents.

Scope: READS caller input, STORAGE_PATH and the vendored Store blocks.
WRITES this capability's own alembic entity through store.save(ENTITY, ...)
and the local storage tree. NEVER performs network I/O, never writes
another tenant's rows, never persists to a table alembic 0001 did not
create.
"""

from __future__ import annotations

import json
from typing import Any, Dict

from app.dispatch import execute

CAPABILITY_ID = "matter_management"
ENTITY = 'matter_management'
BLOCK_IDS = ['workflow', 'database', 'document_engine', 'notification']
#: Each block's declared default action (from its block.json).
#: Blocks are action-dispatched; calling one with no action answers
#: 'Unknown action'.
BLOCK_DEFAULT_ACTIONS = {'workflow': 'run', 'database': 'insert', 'document_engine': 'parse', 'notification': 'send'}
#: This capability's own domain columns, declared so the kernel does
#: not strip a domain field that shares a trust-scope name.
CAPABILITY_FIELDS = ['reference', 'status', 'matter_number', 'matter_title', 'client_name', 'client_email', 'practice_area', 'responsible_attorney', 'matter_stage', 'priority', 'opened_date', 'deadline_date', 'billing_type', 'document_path']
_INSIGHT_KEY = 'matter_state'

REQUIRED_FIELDS = ['reference', 'status', 'matter_number', 'matter_title', 'client_name']

def _text(payload: Dict[str, Any], name: str) -> str:
    value = (payload or {}).get(name)
    return value.strip() if isinstance(value, str) else ("" if value is None else str(value))


def _int(payload: Dict[str, Any], name: str, default: int = 0) -> int:
    value = (payload or {}).get(name)
    if isinstance(value, bool):
        return default
    if isinstance(value, int):
        return value
    try:
        return int(str(value))
    except (TypeError, ValueError):
        return default


def _float(payload: Dict[str, Any], name: str, default: float = 0.0) -> float:
    value = (payload or {}).get(name)
    if isinstance(value, bool):
        return default
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value))
    except (TypeError, ValueError):
        return default


def _email(payload: Dict[str, Any], name: str) -> str:
    value = _text(payload, name)
    return value if "@" in value else ""


def _record(payload: Dict[str, Any]) -> Dict[str, Any]:
    """The capability's own columns only: nothing block-specific leaks out."""
    data = payload if isinstance(payload, dict) else {}
    return {key: data[key] for key in CAPABILITY_FIELDS if key in data}

def _matter_brief(payload: Dict[str, Any]) -> str:
    """The matter brief every reviewer reads: who, what, when, how urgent."""
    parts = [
        "Matter " + (_text(payload, "matter_number") or "unreferenced"),
        "title: " + (_text(payload, "matter_title") or "untitled matter"),
        "client: " + (_text(payload, "client_name") or "unnamed client"),
        "practice area: " + (_text(payload, "practice_area") or "unassigned"),
        "responsible attorney: " + (_text(payload, "responsible_attorney") or "unassigned"),
        "stage: " + (_text(payload, "matter_stage") or "intake"),
        "opened: " + (_text(payload, "opened_date") or "undated"),
        "deadline: " + (_text(payload, "deadline_date") or "none recorded"),
        "billing: " + (_text(payload, "billing_type") or "hourly"),
    ]
    return "; ".join(parts)


def _deadline_state(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Deadline pressure as the firm records it (no clock, no guessing)."""
    deadline = _text(payload, "deadline_date")
    opened = _text(payload, "opened_date")
    stage = _text(payload, "matter_stage") or "intake"
    return {
        "deadline_date": deadline or None,
        "opened_date": opened or None,
        "matter_stage": stage,
        "deadline_recorded": bool(deadline),
        "matter_number": _text(payload, "matter_number"),
    }


def _block_input(block_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    """The object each bound block is handed, built from the matter record."""
    reference = _text(payload, "reference") or "unreferenced"
    number = _text(payload, "matter_number") or reference
    title = _text(payload, "matter_title") or "untitled matter"
    client = _text(payload, "client_name") or "unnamed client"
    attorney = _text(payload, "responsible_attorney") or "unassigned attorney"
    brief = _matter_brief(payload)
    if block_id == "database":
        return {
            "table": ENTITY,
            "values": {key: str(value) for key, value in _record(payload).items()},
        }
    if block_id == "document_engine":
        # The matter brief is the document this capability actually holds; a
        # caller-supplied document_path wins when the file exists on disk.
        return {
            "filename": number + ".txt",
            "content": brief,
            "input": {"reference": reference, "matter_title": title},
            "document_path": _text(payload, "document_path") or None,
        }
    if block_id == "notification":
        return {
            "channel": "email",
            "to": _email(payload, "client_email") or "matters@example.com",
            "subject": "Matter " + number + " opened: " + title,
            "message": brief,
            "block": CAPABILITY_ID,
            "tool": "notification",
        }
    if block_id == "workflow":
        # Every child is prepared: block, action, params.action and a real
        # input. The Store workflow reads the child's operation from params.
        return {
            "steps": [
                {
                    "block": "document_engine",
                    "action": "parse",
                    "params": {"action": "parse"},
                    "input": _block_input("document_engine", payload),
                },
                {
                    "block": "database",
                    "action": "insert",
                    "params": {"action": "insert"},
                    "input": _block_input("database", payload),
                },
                {
                    "block": "notification",
                    "action": "send",
                    "params": {"action": "send"},
                    "input": _block_input("notification", payload),
                },
            ],
            "result": {
                "reference": reference,
                "matter_number": number,
                "matter_title": title,
                "client_name": client,
                "responsible_attorney": attorney,
                "summary": brief,
            },
        }
    return dict(payload)


def _insight(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Matter state the firm reads back off the record."""
    return _deadline_state(payload)

def _normalise_matter(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Matter normalisation: the file always has a number, a title and a stage."""
    data = dict(payload) if isinstance(payload, dict) else {}
    reference = _text(data, "reference") or "unreferenced"
    data["reference"] = reference
    data["matter_number"] = _text(data, "matter_number") or reference
    data["matter_title"] = _text(data, "matter_title") or ("Matter " + reference)
    data["matter_stage"] = (_text(data, "matter_stage") or "intake").lower()
    data["priority"] = (_text(data, "priority") or "normal").lower()
    return data

def _persist_record(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Factory-grounded one-record persist. PRODUCT re-reads this entity.

    Store is imported here, not at module load: isolated contract probes
    exec this file against the factory ``app`` package (no product
    ``app.store``). A generated workspace still has ``app/store.py``.
    """
    record = dict(payload) if isinstance(payload, dict) else {}
    try:
        from app import store as _store
    except ImportError:
        return record
    return _store.save(ENTITY, record)


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    from app.offline_blocks import install_offline_block_adapters
    from app.paths import ensure_runtime_paths

    ensure_runtime_paths()
    payload = _normalise_matter(payload)

    # Sealed-vendor repair path: adopts an offline sink only for a Store
    # runtime module that cannot be imported at all (app/offline_blocks.py).
    install_offline_block_adapters()
    import app.dispatch as _dispatch
    try:
        from app.block_inputs import prepare_block_input as _prepare_block_input
    except ImportError:  # pragma: no cover - unit stubs without the module
        def _prepare_block_input(block_id, data, **_kw):
            return data if isinstance(data, dict) else {'value': data}
    try:
        from app.block_inputs import default_block_action as _default_block_action
    except ImportError:  # pragma: no cover - unit stubs / older emit
        def _default_block_action(block_id, default_actions=None):
            defaults = default_actions if isinstance(default_actions, dict) else {}
            cand = defaults.get(block_id)
            return cand if isinstance(cand, str) and cand.strip() else None
    try:
        from app.block_inputs import split_execute_action as _split_execute_action
    except ImportError:  # pragma: no cover - unit stubs / older emit
        def _split_execute_action(payload, action=None, default_action=None):
            data = dict(payload) if isinstance(payload, dict) else (
                {} if payload is None else {'value': payload}
            )
            inner = data.get('input') if isinstance(data.get('input'), dict) else {}
            resolved = action
            if not (isinstance(resolved, str) and resolved.strip()):
                for cand in (data.get('action'), inner.get('action'), default_action):
                    if isinstance(cand, str) and cand.strip():
                        resolved = cand
                        break
                else:
                    resolved = default_action
            data.pop('action', None)
            if isinstance(data.get('input'), dict):
                data['input'] = dict(data['input'])
                data['input'].pop('action', None)
            return resolved, data
    _block_errors = []
    def _watched(block_id, *a, **kw):
        data = a[0] if a else kw.get('payload', {})
        action = kw.get('action')
        if action is None and len(a) > 1:
            action = a[1]
        params = kw.get('params')
        if params is None and len(a) > 2:
            params = a[2]
        action, data = _split_execute_action(
            data,
            action=action,
            default_action=_default_block_action(
                block_id, BLOCK_DEFAULT_ACTIONS
            ),
        )
        prepared = _prepare_block_input(
            block_id, data, action=action, roster=BLOCK_IDS,
            entity=ENTITY,
            default_actions=BLOCK_DEFAULT_ACTIONS,
        )
        if isinstance(prepared, dict):
            prepared = dict(prepared)
            prepared.pop('action', None)
            if isinstance(prepared.get('input'), dict):
                prepared['input'] = dict(prepared['input'])
                prepared['input'].pop('action', None)
        res = _dispatch.execute(
            block_id, prepared, action=action, params=params
        )
        if isinstance(res, dict) and (
            res.get("status") == "error" or "error" in res
        ):
            _block_errors.append(
                "%s: %s" % (block_id, str(res.get("error") or res.get("status"))[:160])
            )
        return res
    def _impl(payload, execute=_watched):
        results = {}
        errors = {}
        for block_id in BLOCK_IDS:
            result = execute(
                block_id,
                _block_input(block_id, payload),
                action=BLOCK_DEFAULT_ACTIONS.get(block_id),
            )
            results[block_id] = result
            if isinstance(result, dict) and (
                result.get("status") == "error" or "error" in result
            ):
                errors[block_id] = str(result.get("error") or result)[:200]
        if errors:
            return {
                "ok": False,
                "capability": CAPABILITY_ID,
                "error": "; ".join(f"{b}: {e}" for b, e in sorted(errors.items())),
                "results": results,
            }
        stored = _persist_record(payload)
        return {"ok": True, "capability": CAPABILITY_ID, "results": results, "stored": stored}
    result = _impl(payload)
    if isinstance(result, dict) and result.get("ok") is not False:
        result[_INSIGHT_KEY] = _insight(payload)
    if _block_errors and (
        not isinstance(result, dict) or result.get("ok") is not False
    ):
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "block failed: " + "; ".join(_block_errors),
            "result": result,
        }
    if isinstance(result, dict) and result.get('ok') is False:
        return result
    stored = _persist_record(payload)
    if isinstance(result, dict):
        result = dict(result)
        result.setdefault('ok', True)
        result['stored'] = stored
        return result
    return {'ok': True, 'capability': CAPABILITY_ID, 'stored': stored, 'result': result}

"""Offline adapters for sealed Store runtime modules that cannot import.

Written by the factory WRITER role (codewhale exec).

The CLONER vendors the Store runtime under ``vendor/cerebrum/**`` and applies
the factory's offline emission transform to each module. Three modules are
left unusable in this build, and ``vendor/**`` is sealed and read-only, so the
platform cannot repair the bytes it was shipped:

===========================================  =================================
module                                        how it fails
===========================================  =================================
vendor/cerebrum/blocks/notification.py        IndentationError (line 231)
vendor/cerebrum/blocks/knowledge.py           ImportError: vector_store
vendor/cerebrum/blocks/document_engine/       FileNotFoundError:
                                              document_engine_block.py
===========================================  =================================

Each adapter here is installed **only** when the sealed module fails to load,
and each is a real local implementation with an honest answer:

* **notification** spools the message to ``$STORAGE_PATH/notifications.jsonl``
  and reports ``delivered: false, offline: true``. Nothing claims a message
  left the machine.
* **knowledge** answers from the firm's own corpus (``app.retrieval``),
  tenant-scoped, with citations — and says ``grounded: false`` when the corpus
  has no match rather than inventing one.
* **document_engine** extracts text from what it is actually given (plain
  text, JSON, or the caller's own content) and reports ``extracted_from``.

Every other block still dispatches to the sealed Store bytes unchanged, and
the substitutions are reported by ``GET /v1/provenance`` and
``docs/known_limitations.json``.
"""

from __future__ import annotations

import json
import os
import sys
import types
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

PRODUCT_NAME = "LexManage"

_JOURNAL: Dict[str, Dict[str, Any]] = {}
_INSTALLED = False


def _storage_root() -> Path:
    root = Path(os.getenv("STORAGE_PATH") or "./data")
    root.mkdir(parents=True, exist_ok=True)
    return root


# --------------------------------------------------------------------------
# notification
# --------------------------------------------------------------------------


class OfflineNotificationBlock:
    """In-process MCP notification sink with the Store block's async surface.

    The vendored adapter constructs the class positionally, by keyword or with
    no arguments and then awaits ``execute(input_data, params)``; every call
    shape is accepted so the adapter's construction ladder succeeds first try.
    """

    name = "notification"
    version = "offline-adapter.v1"

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        self.config: Dict[str, Any] = dict(kwargs.get("config") or {})
        self._spool = _storage_root() / "notifications.jsonl"

    async def execute(
        self, input_data: Any = None, params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        return self.process(input_data, params)

    def process(
        self, input_data: Any = None, params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        data = input_data if isinstance(input_data, dict) else {"message": input_data}
        opts = params if isinstance(params, dict) else {}
        action = str(opts.get("action") or data.get("action") or "send").strip() or "send"
        if action == "health":
            return {
                "status": "success",
                "result": {"healthy": True, "offline": True, "spool": str(self._spool)},
            }
        if action not in {"send", "broadcast"}:
            return {"status": "error", "error": "Unknown action: " + action}
        message = str(data.get("message") or data.get("body") or "").strip()
        if not message:
            return {"status": "error", "error": "message required"}
        channel = str(data.get("channel") or opts.get("channel") or "mcp").strip().lower()
        record = {
            "channel": channel if channel in {"email", "mcp", "webhook", "slack"} else "mcp",
            "to": str(data.get("to") or data.get("email") or "").strip(),
            "subject": str(data.get("subject") or "").strip(),
            "message": message,
            "block": str(data.get("block") or opts.get("block") or "").strip(),
            "tool": str(data.get("tool") or opts.get("tool") or "notification").strip(),
            "delivered": False,
            "offline": True,
            "reason": "sealed Store notification runtime is not importable",
        }
        with self._spool.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, sort_keys=True) + "\n")
        return {
            "status": "success",
            "result": {
                "sent": False,
                "queued": True,
                "delivered": False,
                "offline": True,
                "channel": record["channel"],
                "block": record["block"],
                "spool": str(self._spool),
                "preview": message[:200],
            },
        }

    def get_status(self) -> Dict[str, Any]:
        return {"status": "success", "name": self.name, "offline": True}


# --------------------------------------------------------------------------
# knowledge
# --------------------------------------------------------------------------


class OfflineKnowledgeBlock:
    """Corpus-backed answer surface for the sealed knowledge runtime."""

    name = "knowledge"
    version = "offline-adapter.v1"

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        self.config: Dict[str, Any] = dict(kwargs.get("config") or {})
        self.tenant = str(os.getenv("LEXMANAGE_DEFAULT_TENANT") or "local")

    async def execute(
        self, input_data: Any = None, params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        return self.process(input_data, params)

    def process(
        self, input_data: Any = None, params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        from app import retrieval

        data = input_data if isinstance(input_data, dict) else {"query": input_data}
        opts = params if isinstance(params, dict) else {}
        action = str(opts.get("action") or data.get("action") or "ask").strip() or "ask"
        if action not in {"ask", "search", "summarize"}:
            return {"status": "error", "error": "Unknown action: " + action}
        query = str(
            data.get("query") or data.get("question") or data.get("text") or ""
        ).strip()
        if not query:
            return {"status": "error", "error": "query required"}
        collection = data.get("collection")
        collections = [str(collection)] if collection else None
        top_k = data.get("top_k")
        try:
            top_k = int(top_k)
        except (TypeError, ValueError):
            top_k = 5
        retrieval.seed_firm_guidance(self.tenant)
        hits = retrieval.search(self.tenant, query, top_k=top_k, collections=collections)
        answer = {
            "answer": (hits[0]["text"] if hits else ""),
            "results": hits,
            "grounded": bool(hits),
            "offline": True,
            "collection": collection or "firm_corpus",
            "corpus_total": len(retrieval.index_for(self.tenant).documents),
        }
        if action == "summarize" and hits:
            from app import llm

            answer["summary"] = llm.summarize(hits[0]["text"])["summary"]
        return {"status": "success", "result": answer}

    def get_status(self) -> Dict[str, Any]:
        return {"status": "success", "name": self.name, "offline": True}


# --------------------------------------------------------------------------
# document_engine
# --------------------------------------------------------------------------


class OfflineDocumentEngineBlock:
    """Text extraction from what the caller actually supplied."""

    name = "document_engine"
    version = "offline-adapter.v1"

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        self.config: Dict[str, Any] = dict(kwargs.get("config") or {})

    async def execute(
        self, input_data: Any = None, params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        return self.process(input_data, params)

    def process(
        self, input_data: Any = None, params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        data = input_data if isinstance(input_data, dict) else {"content": input_data}
        opts = params if isinstance(params, dict) else {}
        action = str(opts.get("action") or data.get("action") or "parse").strip() or "parse"
        if action not in {"parse"}:
            return {"status": "error", "error": "Unknown action: " + action}
        text = str(data.get("content") or data.get("text") or "").strip()
        origin = "payload"
        path = str(data.get("file_path") or data.get("path") or "").strip()
        if not text and path:
            candidate = Path(path)
            if candidate.is_file():
                suffix = candidate.suffix.lower()
                if suffix in {".txt", ".md", ".csv", ".json", ".log"}:
                    text = candidate.read_text(encoding="utf-8", errors="replace")
                    origin = suffix.lstrip(".") or "text"
                elif suffix == ".pdf":
                    raw = candidate.read_bytes()
                    text = " ".join(
                        chunk.decode("latin-1", errors="ignore")
                        for chunk in raw.split(b"stream")[1:2]
                    ).strip()
                    origin = "pdf-text-stream" if text else "pdf-binary"
                else:
                    text = candidate.read_text(encoding="utf-8", errors="replace")
                    origin = suffix.lstrip(".") or "text"
            else:
                origin = "missing-file"
        if not text:
            return {
                "status": "success",
                "result": {
                    "text": "",
                    "characters": 0,
                    "extracted_from": origin,
                    "offline": True,
                    "note": "no extractable text supplied; nothing was invented",
                },
            }
        return {
            "status": "success",
            "result": {
                "text": text,
                "characters": len(text),
                "extracted_from": origin,
                "offline": True,
            },
        }

    def get_status(self) -> Dict[str, Any]:
        return {"status": "success", "name": self.name, "offline": True}


#: import name → (module path on disk, class the vendored adapter asks for, class)
_ADAPTERS: Tuple[Tuple[str, str, str, Any], ...] = (
    (
        "vendor.cerebrum.blocks.notification",
        "vendor/cerebrum/blocks/notification.py",
        "NotificationBlock",
        OfflineNotificationBlock,
    ),
    (
        "vendor.cerebrum.blocks.knowledge",
        "vendor/cerebrum/blocks/knowledge.py",
        "KnowledgeBlock",
        OfflineKnowledgeBlock,
    ),
    (
        "vendor.cerebrum.blocks.document_engine",
        "vendor/cerebrum/blocks/document_engine/__init__.py",
        "DocumentEngineBlock",
        OfflineDocumentEngineBlock,
    ),
)


def _root() -> Path:
    return Path(__file__).resolve().parents[1]


def _module_unimportable(module_name: str, relpath: str) -> bool:
    """True when the sealed module cannot be imported at all."""
    if module_name in sys.modules:
        return False
    path = _root() / relpath
    if not path.exists():
        return True
    try:
        compile(path.read_text(encoding="utf-8"), str(path), "exec")
    except (OSError, SyntaxError):
        return True
    import importlib

    try:
        importlib.import_module(module_name)
    except Exception:  # noqa: BLE001 - any import failure is the trigger
        return True
    return False


def install_offline_block_adapters() -> Tuple[str, ...]:
    """Adopt an offline adapter for each sealed module that cannot import.

    Idempotent. Returns the import names adopted; an empty tuple means the
    sealed vendor was importable and nothing was substituted.
    """
    global _INSTALLED
    if _INSTALLED:
        return ()
    adopted: List[str] = []
    for module_name, relpath, class_name, adapter in _ADAPTERS:
        if not _module_unimportable(module_name, relpath):
            continue
        module = types.ModuleType(module_name)
        module.__doc__ = (
            "Offline adapter registered by app.offline_blocks: the sealed "
            "vendored module is not importable in this build."
        )
        setattr(module, class_name, adapter)
        sys.modules[module_name] = module
        adopted.append(module_name)
        _JOURNAL[module_name] = {
            "adapter": adapter.__name__,
            "sealed_path": relpath,
            "reason": "sealed vendored module is not importable",
        }
    _INSTALLED = True
    return tuple(adopted)


def offline_block_notes() -> Dict[str, Any]:
    """What was substituted, for docs and GET /v1/provenance."""
    adopted = install_offline_block_adapters()
    entries = []
    for module_name, relpath, class_name, adapter in _ADAPTERS:
        notes = _JOURNAL.get(module_name)
        entries.append(
            {
                "import_name": module_name,
                "sealed_path": relpath,
                "expected_class": class_name,
                "adapter": (notes or {}).get("adapter"),
                "substituted": bool(notes),
                "importable_after_install": module_name in sys.modules,
            }
        )
    return {
        "product": PRODUCT_NAME,
        "adopted": list(adopted),
        "entries": entries,
        "notification_spool": str(_storage_root() / "notifications.jsonl"),
        "truth": (
            "No network is used. Notifications are spooled locally and reported "
            "delivered:false; knowledge answers come from this platform's own "
            "tenant-scoped corpus with citations."
        ),
    }

"""Block input construction for this platform.

Generated by the factory WRITER. Handlers call prepare_block_input (via the
fail-closed execute wrapper) so domain records become block-acceptable
payloads without requiring the caller to know about channel/steps/paths.
"""

from __future__ import annotations

import json
import os
import re
import tempfile
from typing import Any, Dict, List, Optional, Sequence, Tuple

STORE_BLOCK_DEFAULT_ACTIONS = {'analytics': 'track_event', 'audit': 'log', 'capture': 'extract', 'capture_v2': 'extract', 'dashboard': 'render', 'database': 'query', 'document_engine': 'parse', 'event_bus': 'publish', 'formula_executor': 'execute', 'formula_executor_v2': 'execute', 'notification': 'send', 'queue': 'enqueue', 'team': 'create_team', 'validation': 'validate', 'vector_search': 'search', 'workflow': 'run', 'spec_analyzer': 'analyze', 'recommendation_template': 'apply_template', 'readiness_engine': 'score', 'storage': 'store', 'estate_registry': 'register', 'estate_maintenance': 'plan_work', 'evidence_verifier': 'verify', 'portfolio_rollup': 'aggregate', 'knowledge': 'search'}


def default_block_action(block_id, default_actions=None):
    """Keyword action for execute(..., action=). Never invent from payload."""
    bid = str(block_id or "").strip()
    if isinstance(default_actions, dict):
        cand = default_actions.get(bid)
        if isinstance(cand, str) and cand.strip():
            return cand.strip()
    mapped = STORE_BLOCK_DEFAULT_ACTIONS.get(bid)
    if isinstance(mapped, str) and mapped.strip():
        return mapped.strip()
    return None


_QUEUE_INT_KEYS = (
    "id",
    "priority",
    "delay",
    "delay_seconds",
    "timeout",
    "visibility_timeout",
    "attempts",
    "max_attempts",
    "retry_count",
    "item_id",
)
_DOC_PATH_KEYS = (
    "file_path",
    "pdf_path",
    "docx_path",
    "xlsx_path",
    "attachment_path",
    "document_path",
    "path",
)
_TEAM_STRING_KEYS = ("user_id", "name", "slug", "role", "email", "plan", "permission")
_TOPIC_KEYS = ("topic", "event", "event_type", "event_name", "reminder_type")
_MINIMAL_PDF = (
    b"%PDF-1.1\n"
    b"1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n"
    b"2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj\n"
    b"3 0 obj<</Type/Page/MediaBox[0 0 3 3]>>endobj\n"
    b"trailer<</Size 4/Root 1 0 R>>\n"
)
_SYNTH_DOC_PATH = None
_SKIP = frozenset(
    {
        "ok",
        "error",
        "capability",
        "id",
        "status",
        "result",
        "results",
        "payload",
        "action",
        "block",
        "blocks",
        "channel",
        "message",
        "steps",
        "team_id",
    }
)


def split_execute_action(
    payload: Any,
    *,
    action: Optional[str] = None,
    default_action: Optional[str] = None,
) -> Tuple[Optional[str], Dict[str, Any]]:
    data = dict(payload) if isinstance(payload, dict) else (
        {} if payload is None else {"value": payload}
    )
    inner = data.get("input") if isinstance(data.get("input"), dict) else {}

    def _usable(value):
        if isinstance(value, str) and value.strip():
            return value
        return None

    resolved = (
        _usable(action)
        or _usable(data.get("action"))
        or _usable(inner.get("action"))
        or _usable(default_action)
    )
    data.pop("action", None)
    if isinstance(data.get("input"), dict):
        cleaned = dict(data["input"])
        cleaned.pop("action", None)
        data["input"] = cleaned
    return resolved, data


def prepare_block_input(
    block_id: str,
    domain: Any,
    *,
    action: Optional[str] = None,
    roster: Sequence[str] = (),
    product_name: str = "platform",
    entity: Optional[str] = None,
    default_actions: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    _resolved, data = split_execute_action(domain, action=action)
    bid = str(block_id or "")
    merged_actions = dict(STORE_BLOCK_DEFAULT_ACTIONS)
    if default_actions:
        merged_actions.update(default_actions)
    if bid == "notification":
        return _for_notification(data, roster)
    if bid == "workflow":
        return _for_workflow(
            data,
            roster,
            product_name=product_name,
            entity=entity,
            default_actions=merged_actions,
        )
    if bid == "team":
        return _for_team(data, product_name=product_name)
    if bid == "document_engine":
        return _for_document_engine(data)
    if bid == "analytics":
        return _for_analytics(data)
    if bid == "event_bus":
        return _for_event_bus(data, roster)
    if bid == "database":
        return _for_database(data, entity=entity)
    if bid == "queue":
        return _for_queue(data)
    if bid == "dashboard":
        return _for_dashboard(data)
    return data


def _summary_message(data: Dict[str, Any]) -> str:
    parts = [
        f"{key}={value}"
        for key, value in data.items()
        if isinstance(value, (str, int, float, bool)) and key not in _SKIP
    ]
    return (("; ".join(parts)).strip() or "platform notification")[:500]


def _for_dashboard(data: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(data)
    inner = out.get("input") if isinstance(out.get("input"), dict) else {}
    status = out.get("status") if out.get("status") is not None else inner.get("status")
    if not (isinstance(status, str) and status.strip()):
        out["status"] = "open"
    elif not out.get("status"):
        out["status"] = status
    return out


def _notification_channel(value, data=None):
    raw = str(value or "").strip().lower()
    payload = data if isinstance(data, dict) else {}
    if raw == "mcp":
        return "mcp"
    if raw == "email":
        to = payload.get("to") or payload.get("email")
        if isinstance(to, str) and to.strip() and "@" in to:
            return "email"
        return "mcp"
    if raw == "webhook":
        url = payload.get("url") or payload.get("webhook_url")
        if isinstance(url, str) and url.startswith(("http://", "https://")):
            return "webhook"
        return "mcp"
    if raw == "slack":
        if payload.get("webhook_url") or payload.get("slack_webhook_url"):
            return "slack"
        return "mcp"
    return "mcp"


def _for_notification(data: Dict[str, Any], roster: Sequence[str]) -> Dict[str, Any]:
    out = dict(data)
    out["channel"] = _notification_channel(out.get("channel"), out)
    if not out.get("message"):
        body = out.get("body")
        out["message"] = (
            body if isinstance(body, str) and body.strip() else _summary_message(data)
        )
    if str(out.get("channel")).lower() == "mcp" and not out.get("block") and not out.get("tool"):
        peers = [b for b in roster if b and b != "notification"]
        out["block"] = peers[0] if peers else "notification"
    return out


def _workflow_step_block(step):
    for key in ("block", "block_id", "name"):
        value = step.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return ""


def _step_action(block_id, default_actions):
    return default_block_action(block_id, default_actions)


def _shape_workflow_steps(
    steps,
    roster,
    *,
    product_name,
    entity,
    default_actions,
    fallback_domain,
):
    shaped = []
    for step in steps:
        if not isinstance(step, dict):
            shaped.append(step)
            continue
        item = dict(step)
        bid = _workflow_step_block(item)
        if not bid:
            shaped.append(item)
            continue
        raw = item.get("input")
        payload = raw if isinstance(raw, dict) else fallback_domain
        item["block"] = bid
        item["input"] = prepare_block_input(
            bid,
            payload,
            roster=roster,
            product_name=product_name,
            entity=entity,
            default_actions=default_actions,
        )
        if not item.get("action"):
            action = _step_action(bid, default_actions)
            if action:
                item["action"] = action
        shaped.append(item)
    return shaped


def _workflow_result_payload(data, steps=None):
    if isinstance(data, dict):
        existing = data.get("result")
        if existing not in (None, ""):
            return existing
    chain = steps
    if chain is None and isinstance(data, dict):
        chain = data.get("steps")
    for step in chain or ():
        if not isinstance(step, dict):
            continue
        inner = step.get("input")
        if isinstance(inner, dict) and inner:
            return dict(inner)
        if inner not in (None, ""):
            return inner
    if not isinstance(data, dict):
        return {"reference": "record"}
    scalars = {
        key: value
        for key, value in data.items()
        if key not in {
            "steps",
            "action",
            "result",
            "results",
            "input",
            "ok",
            "error",
            "block",
            "blocks",
        }
        and value not in (None, "")
    }
    return scalars or {"reference": data.get("reference") or "record"}


def _ensure_workflow_result(data, steps=None):
    out = dict(data) if isinstance(data, dict) else {}
    if steps is not None:
        out["steps"] = list(steps)
    if out.get("result") not in (None, ""):
        return out
    out["result"] = _workflow_result_payload(out, out.get("steps"))
    return out


def _for_workflow(
    data: Dict[str, Any],
    roster: Sequence[str],
    *,
    product_name: str = "platform",
    entity: Optional[str] = None,
    default_actions: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    out = dict(data)
    steps = out.get("steps")
    if isinstance(steps, list) and steps:
        out["steps"] = _shape_workflow_steps(
            steps,
            roster,
            product_name=product_name,
            entity=entity,
            default_actions=default_actions,
            fallback_domain=data,
        )
        return _ensure_workflow_result(out)
    peers = [b for b in roster if b and b != "workflow"]
    built: List[Dict[str, Any]] = []
    for block in peers[:3]:
        step = {
            "block": block,
            "input": prepare_block_input(
                block,
                data,
                roster=roster,
                product_name=product_name,
                entity=entity,
                default_actions=default_actions,
            ),
        }
        action = _step_action(block, default_actions)
        if action:
            step["action"] = action
        built.append(step)
    if not built:
        built.append({"block": "workflow", "input": dict(data)})
    out["steps"] = built
    return _ensure_workflow_result(out)


def _looks_minted_team_id(value):
    if not isinstance(value, str):
        return False
    body = value[5:] if value.startswith("team_") else ""
    return len(body) >= 8 and all(c in "0123456789abcdefABCDEF" for c in body)


def _platform_team_id():
    try:
        from app.preconditions import resource_id
    except Exception:
        return None
    tid = resource_id("team")
    if tid:
        return str(tid)
    try:
        from app.preconditions import ensure_all

        ensure_all()
    except Exception:
        return None
    tid = resource_id("team")
    return str(tid) if tid else None


def _for_team(data: Dict[str, Any], *, product_name: str = "platform") -> Dict[str, Any]:
    out = dict(data)
    for key in _TEAM_STRING_KEYS:
        if key in out and out[key] is None:
            out.pop(key)
    slug_base = re.sub(r"[^a-z0-9-]+", "-", (product_name or "platform").lower()).strip("-")
    slug_base = slug_base or "platform"
    out.setdefault("user_id", "system")
    out.setdefault("name", f"{product_name or 'platform'} team")
    out.setdefault("slug", f"{slug_base}-team")
    minted = _platform_team_id()
    current = out.get("team_id")
    if minted and (not current or not _looks_minted_team_id(current)):
        out["team_id"] = minted
    for key in _TEAM_STRING_KEYS:
        if key in out and out[key] is None:
            out.pop(key)
        elif key in out and not isinstance(out[key], str):
            out[key] = str(out[key])
    return out


def _existing_file_path(value):
    if not isinstance(value, str) or not value.strip():
        return None
    try:
        return value if os.path.isfile(value) else None
    except OSError:
        return None


def _synthesized_document_path():
    global _SYNTH_DOC_PATH
    if _SYNTH_DOC_PATH and os.path.isfile(_SYNTH_DOC_PATH):
        return _SYNTH_DOC_PATH
    fd, path = tempfile.mkstemp(prefix="platform-doc-", suffix=".pdf")
    with os.fdopen(fd, "wb") as handle:
        handle.write(_MINIMAL_PDF)
    _SYNTH_DOC_PATH = path
    return path


def _for_document_engine(data: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(data)
    inner = out.get("input") if isinstance(out.get("input"), dict) else {}
    for key in _DOC_PATH_KEYS:
        if isinstance(out.get(key), dict):
            out.pop(key)
        elif key not in out and _existing_file_path(inner.get(key)):
            out[key] = inner[key]
    existing = None
    for key in _DOC_PATH_KEYS:
        existing = _existing_file_path(out.get(key))
        if existing:
            out.setdefault("file_path", existing)
            out.setdefault("pdf_path", existing)
            break
    text = out.get("text")
    if not (isinstance(text, str) and text.strip()):
        lines = [
            f"{key}: {value}"
            for key, value in data.items()
            if isinstance(value, (str, int, float, bool))
        ]
        out["text"] = "\n".join(lines) if lines else json.dumps(data, default=str)
    if existing:
        return out
    path = _synthesized_document_path()
    out["file_path"] = path
    out["pdf_path"] = path
    return out


def _for_analytics(data: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(data)
    inner = out.get("input") if isinstance(out.get("input"), dict) else {}
    for key in ("metric", "value"):
        if key not in out and key in inner:
            out[key] = inner[key]
    if not out.get("metric"):
        for key, value in data.items():
            if key != "input" and isinstance(value, str) and value:
                out["metric"] = key
                break
        out.setdefault("metric", "event")
    if out.get("value") is None:
        for key, value in data.items():
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                out["value"] = value
                break
        out.setdefault("value", 1)
    return out


def _topic_from_domain(data):
    slug = re.sub(r"[^a-zA-Z0-9_.-]+", ".", _summary_message(data)).strip(".")
    return (slug or "platform.event")[:80]


def _for_event_bus(data, roster=()):
    inner = data.get("input") if isinstance(data.get("input"), dict) else {}
    topic = data.get("topic") or inner.get("topic")
    if not (isinstance(topic, str) and topic.strip()):
        for key in _TOPIC_KEYS:
            if key == "topic":
                continue
            cand = data.get(key) if data.get(key) is not None else inner.get(key)
            if isinstance(cand, str) and cand.strip():
                topic = cand.strip()
                break
        else:
            topic = _topic_from_domain(data)
    topic = str(topic).strip()
    payload = data.get("payload") if isinstance(data.get("payload"), dict) else None
    if payload is None and isinstance(inner.get("payload"), dict):
        payload = inner["payload"]
    if not isinstance(payload, dict):
        payload = {
            key: value
            for key, value in data.items()
            if key not in _SKIP and isinstance(value, (str, int, float, bool))
        } or {"topic": topic}
    message = data.get("message") if isinstance(data.get("message"), str) else ""
    if not str(message).strip():
        inner_msg = inner.get("message")
        message = inner_msg if isinstance(inner_msg, str) and inner_msg.strip() else _summary_message(data)
    channel = _notification_channel(
        data.get("channel") if data.get("channel") is not None else inner.get("channel"),
        data,
    )
    return {
        "topic": topic,
        "payload": dict(payload),
        "data": dict(payload),
        "event": topic,
        "message": str(message).strip() or _summary_message(data),
        "channel": channel,
        "block": "event_bus",
        "tool": "event_bus",
    }


def _coerce_int(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, str) and value.strip().lstrip("-").isdigit():
        return int(value.strip())
    return None


def _for_queue(data: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(data)
    inner = out.get("input") if isinstance(out.get("input"), dict) else {}
    for key in _QUEUE_INT_KEYS:
        raw = out[key] if key in out else inner.get(key)
        if raw is None:
            continue
        coerced = _coerce_int(raw)
        if coerced is not None:
            out[key] = coerced
    if out.get("item_id") is None:
        aliased = _coerce_int(out.get("id"))
        if aliased is not None:
            out["item_id"] = aliased
    elif out.get("id") is None:
        aliased = _coerce_int(out.get("item_id"))
        if aliased is not None:
            out["id"] = aliased
    for key in ("priority", "delay", "delay_seconds", "timeout", "visibility_timeout", "attempts", "max_attempts", "retry_count"):
        if key in out and _coerce_int(out[key]) is None:
            out[key] = 0
    for key in ("id", "item_id"):
        if key in out and _coerce_int(out[key]) is None:
            out.pop(key)
    if "payload" not in out and "item" not in out:
        out["payload"] = {
            key: value
            for key, value in data.items()
            if key not in _SKIP
            and key not in {"payload", "item", "input"}
            and isinstance(value, (str, int, float, bool))
        }
    out.setdefault("priority", 0)
    return out


def _usable_table_name(value):
    if isinstance(value, str) and re.match(r"^[A-Za-z_][\w]*$", value.strip()):
        return value.strip()
    return None


_SQL_RECORDS_TABLE = re.compile(
    r"\b(FROM|INTO|UPDATE|JOIN|TABLE)\s+records\b",
    re.IGNORECASE,
)


def _retarget_records_sql(sql, entity):
    return _SQL_RECORDS_TABLE.sub(lambda match: f"{match.group(1)} {entity}", sql)


def _for_database(data: Dict[str, Any], *, entity: Optional[str] = None) -> Dict[str, Any]:
    out = dict(data)
    inner = out.get("input") if isinstance(out.get("input"), dict) else {}
    for key in ("sql", "table", "table_name", "values"):
        if key not in out and key in inner:
            out[key] = inner[key]
    entity_table = _usable_table_name(entity)
    sql = out.get("sql")
    if isinstance(sql, str) and sql.strip():
        if entity_table and _SQL_RECORDS_TABLE.search(sql):
            out["sql"] = _retarget_records_sql(sql, entity_table)
            out["table"] = entity_table
        return out
    table = _usable_table_name(out.get("table") or out.get("table_name"))
    if table == "records" and entity_table:
        table = entity_table
    if not table:
        for key in ("entity", "table", "table_name"):
            table = _usable_table_name(out.get(key) or inner.get(key))
            if table and table != "records":
                break
            if table == "records" and entity_table:
                table = entity_table
                break
    if not table:
        table = entity_table
    if not table:
        table = "records"
    out["table"] = table
    if not isinstance(out.get("values"), dict):
        values = {
            key: value
            for key, value in data.items()
            if key not in _SKIP
            and key not in {"sql", "table", "table_name", "values", "input", "entity"}
            and isinstance(value, (str, int, float, bool))
        }
        if values:
            out["values"] = values
    return out

